{tiles([("NAMES REPLAYED", str(Q1['names']), "1d · 3d · 1w rungs, Alan's weights"), ("PULLBACK CELL", n2(allpb['x63']['med'], True) + " pts", f"next 63 vs SPY · any day {n2(allpb['x63_base']['med'], True)} · {pc(sw['share'])} of days"), ("WEAK + WEAK", n2(ww['x63']['med'], True) + " pts", f"{rng(ww['x63']['lo'], ww['x63']['hi'], n2)} · {ww['x63']['word']}"), ("INDEX FUNDS REDDER", f"{idxRedder} of {idxN}", "on their own-history scale, by more than 0.2")])}
