{tiles([("RSI ALONE, TOP 10%", n2(rsi10['fwd_21']['med'], True) + "%", f"next 21 · any day {n2(Q2['base']['fwd_21']['p50'], True)}% · {rsi10['runs']} visits · {rsi10['fwd_21']['word']}"), ("VIX LEVEL ALONE", n2(vix10['fwd_21']['med'], True) + "%", f"{rng(vix10['fwd_21']['lo'], vix10['fwd_21']['hi'], n2)} · {vix10['fwd_21']['word']}"), ("LUCK-PROOF COMBOS", f"{len(lp10)} of {Q2['combos']['low_10']['tests']}", "top-10% line, next 21 sessions"), ("AT TOPS", f"{len(lpH)}", "greed combinations that clear the check")])}
